class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        words = set(wordDict)
        memo = {}
        def dfs(k):
            if k in memo: return memo[k]
            if k == len(s): return [""]
            res = []
            for end in range(k + 1, len(s) + 1):
                w = s[k:end]
                if w in words:
                    for sub in dfs(end):
                        res.append((w + " " + sub).strip())
            memo[k] = res
            return res
        return sorted(dfs(0))

